#pragma once
/// @file ml/dga_classifier.h
/// Detector 1 of README §7.8: is a name's registrable label generated by a
/// DGA? Loads the model ml/dga trains (models/dga: dga_lgbm.txt,
/// features.txt, public_suffixes.txt; ml/dga/export.py) and scores one
/// name at a time, in microseconds (experiment E9).
///
/// Scores and verdicts equal ml/dga/scorer.py's: tests/unit/ml checks that
/// on names the Python code scored. The classifier is immutable once
/// loaded; scoring allocates a little but needs no locking.

#include "dnsentinel/ml/dga_features.h"
#include "dnsentinel/ml/gbdt.h"
#include "dnsentinel/ml/psl.h"

#include <expected>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace dnsentinel::ml {

struct DgaVerdict {
    std::string registrable;  // the name the verdict is about: "example.co.uk"
    double      score = 0;    // the model's probability of a DGA name
    bool        dga   = false;
};

class DgaClassifier {
public:
    /// `folder`: the model; `words`: the word list it was trained with
    /// (config/english_words.txt), checked against features.txt's SHA-256.
    [[nodiscard]] static std::expected<DgaClassifier, std::string> load(const std::string& folder,
                                                                         const std::string& words);

    /// nullopt for a name the model can't score (characters no host name
    /// has, an empty label): it is left alone.
    [[nodiscard]] std::optional<DgaVerdict> classify(std::string_view domain) const;
    /// The model's inputs for a name, in its feature order (for tests and the parity check).
    [[nodiscard]] std::optional<std::vector<double>> inputs(std::string_view domain) const;
    /// The registrable domain the verdict for `domain` would be about, without scoring it.
    [[nodiscard]] std::optional<std::string> registrable(std::string_view domain) const;
    /// classify() in two steps, for callers that look the split name up first.
    [[nodiscard]] std::optional<SplitName> split(std::string_view domain) const { return split_name(domain, psl_); }
    [[nodiscard]] DgaVerdict               classify(const SplitName& name) const;

    [[nodiscard]] double                          threshold() const { return threshold_; }
    void                                          set_threshold(double threshold) { threshold_ = threshold; }
    [[nodiscard]] const std::vector<std::string>& features() const { return names_; }
    [[nodiscard]] const PublicSuffixList&         psl() const { return psl_; }
    [[nodiscard]] const GradientBoostedTrees&     trees() const { return trees_; }

private:
    DgaClassifier(PublicSuffixList psl, GradientBoostedTrees trees) : psl_(std::move(psl)), trees_(std::move(trees)) {}
    [[nodiscard]] std::vector<double> select(const FeatureVector& all) const;

    PublicSuffixList         psl_;
    GradientBoostedTrees     trees_;
    FeatureTables            tables_;
    std::vector<std::string> names_;    // the model's inputs, in order
    std::vector<size_t>      columns_;  // where each sits in a FeatureVector
    double                   threshold_ = 0.5;
};

/// SHA-256 of a file, in lower-case hex; nullopt if it can't be read.
[[nodiscard]] std::optional<std::string> sha256_file(const std::string& path);

}  // namespace dnsentinel::ml
